package com.bacursortimer;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BACursorTimerConfig.GROUP)
public interface BACursorTimerConfig extends Config
{
	String GROUP = "baCursorTimer";

	@ConfigItem(
		keyName = "textColor",
		name = "Text color",
		description = "Color of the wave timer.",
		position = 0
	)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@Range(min = -200, max = 200)
	@ConfigItem(
		keyName = "offsetX",
		name = "Horizontal offset",
		description = "Pixels right of the cursor to draw the timer.",
		position = 1
	)
	default int offsetX()
	{
		return 16;
	}

	@Range(min = -200, max = 200)
	@ConfigItem(
		keyName = "offsetY",
		name = "Vertical offset",
		description = "Pixels below the cursor to draw the timer.",
		position = 2
	)
	default int offsetY()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "font",
		name = "Font",
		description = "Font of the wave timer.",
		position = 3
	)
	default TimerFont font()
	{
		return TimerFont.RUNESCAPE;
	}

	@ConfigItem(
		keyName = "bold",
		name = "Bold",
		description = "Draw the wave timer in bold.",
		position = 4
	)
	default boolean bold()
	{
		return true;
	}

	@Range(min = 8, max = 64)
	@ConfigItem(
		keyName = "fontSize",
		name = "Font size",
		description = "Size of the wave timer text. 16 is the game's normal size.",
		position = 5
	)
	default int fontSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "showBackground",
		name = "Background",
		description = "Draw a rectangle behind the wave timer.",
		position = 6
	)
	default boolean showBackground()
	{
		return false;
	}

	@ConfigItem(
		keyName = "backgroundColor",
		name = "Background color",
		description = "Color of the rectangle behind the wave timer.",
		position = 7
	)
	default Color backgroundColor()
	{
		return Color.BLACK;
	}

	@Range(max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "backgroundOpacity",
		name = "Background opacity",
		description = "Opacity of the rectangle behind the wave timer, from 0 (invisible) to 100 (solid).",
		position = 8
	)
	default int backgroundOpacity()
	{
		return 50;
	}
}

package com.bacursortimer;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.ColorUtil;

class BACursorTimerOverlay extends Overlay
{
	private static final int BACKGROUND_PADDING = 2;

	private final Client client;
	private final BACursorTimerPlugin plugin;
	private final BACursorTimerConfig config;

	private Font font;
	private TimerFont fontType;
	private boolean fontBold;
	private int fontSize;

	@Inject
	private BACursorTimerOverlay(Client client, BACursorTimerPlugin plugin, BACursorTimerConfig config)
	{
		super(plugin);
		setPosition(OverlayPosition.DYNAMIC);
		// Drawn in the client's final pass, after interfaces, the right-click menu
		// and tooltips, and last among the cursor-following overlays there
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(PRIORITY_HIGHEST);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WaveClock clock = plugin.getWaveClock();
		if (!clock.isRunning())
		{
			return null;
		}

		// (-1, -1) while the cursor is outside the game canvas
		Point mouse = client.getMouseCanvasPosition();
		if (mouse.getX() < 0 || mouse.getY() < 0)
		{
			return null;
		}

		String text = WaveClock.format(clock.elapsedTicks(client.getTickCount()));

		graphics.setFont(font());
		FontMetrics metrics = graphics.getFontMetrics();
		// Center the text vertically on the cursor, then apply the configured offset
		int x = mouse.getX() + config.offsetX();
		int y = mouse.getY() + config.offsetY() + (metrics.getAscent() - metrics.getDescent()) / 2;

		if (config.showBackground())
		{
			int alpha = Math.round(config.backgroundOpacity() * 255 / 100f);
			graphics.setColor(ColorUtil.colorWithAlpha(config.backgroundColor(), alpha));
			graphics.fill(backgroundBounds(x, y, metrics, text));
		}

		OverlayUtil.renderTextLocation(graphics, new Point(x, y), text, config.textColor());
		return null;
	}

	/**
	 * The rectangle behind text drawn with its baseline at ({@code x}, {@code baseline}),
	 * covering the text and its one-pixel drop shadow plus padding on every side.
	 */
	static Rectangle backgroundBounds(int x, int baseline, FontMetrics metrics, String text)
	{
		return new Rectangle(
			x - BACKGROUND_PADDING,
			baseline - metrics.getAscent() - BACKGROUND_PADDING,
			metrics.stringWidth(text) + 1 + 2 * BACKGROUND_PADDING,
			metrics.getAscent() + metrics.getDescent() + 1 + 2 * BACKGROUND_PADDING);
	}

	private Font font()
	{
		TimerFont type = config.font();
		boolean bold = config.bold();
		int size = config.fontSize();
		if (font == null || type != fontType || bold != fontBold || size != fontSize)
		{
			font = type.font(bold, size);
			fontType = type;
			fontBold = bold;
			fontSize = size;
		}
		return font;
	}
}

package com.bacursortimer;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "BA Cursor Timer",
	description = "Shows the current Barbarian Assault wave time, to the tick, next to the mouse cursor.",
	tags = {"barbarian", "assault", "minigame", "overlay", "timer", "tick", "mouse"}
)
public class BACursorTimerPlugin extends Plugin
{
	// Same wave-start and wave-end signals as the Barbarian Assault plugin's
	// "Wave N duration" chat message, so the two agree on a wave's length.
	private static final String WAVE_START_PREFIX = "---- Wave:";

	@Getter(AccessLevel.PACKAGE)
	private final WaveClock waveClock = new WaveClock();

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BACursorTimerOverlay overlay;

	@Provides
	BACursorTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BACursorTimerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		waveClock.stop();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE && event.getMessage().startsWith(WAVE_START_PREFIX))
		{
			// Counting from the message's own tick reads one tick ahead of the wave
			// (checked in game), so the wave's first tick is the one after it.
			// The clock reads 0.0 until then.
			waveClock.start(client.getTickCount() + 1);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// Set while inside a wave, cleared on leaving it (completion, death or exiting)
		if (event.getVarbitId() == VarbitID.BARBASSAULT_AREAEXIT_PENDING && event.getValue() == 0)
		{
			waveClock.stop();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			waveClock.stop();
		}
	}
}

package com.bacursortimer;

import java.awt.Font;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.FontManager;

@RequiredArgsConstructor
public enum TimerFont
{
	RUNESCAPE("RuneScape")
	{
		@Override
		Font base(boolean bold)
		{
			// The game ships a separate bold face, so use it rather than a synthetic bold
			return bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont();
		}
	},
	RUNESCAPE_SMALL("RuneScape Small")
	{
		@Override
		Font base(boolean bold)
		{
			return FontManager.getRunescapeSmallFont().deriveFont(style(bold));
		}
	},
	SANS_SERIF("Sans-serif")
	{
		@Override
		Font base(boolean bold)
		{
			return new Font(Font.SANS_SERIF, style(bold), BASE_SIZE);
		}
	},
	SERIF("Serif")
	{
		@Override
		Font base(boolean bold)
		{
			return new Font(Font.SERIF, style(bold), BASE_SIZE);
		}
	},
	MONOSPACED("Monospaced")
	{
		@Override
		Font base(boolean bold)
		{
			return new Font(Font.MONOSPACED, style(bold), BASE_SIZE);
		}
	};

	private static final int BASE_SIZE = 16;

	private final String name;

	/**
	 * The font to draw the timer in, before the configured size is applied.
	 */
	abstract Font base(boolean bold);

	Font font(boolean bold, int size)
	{
		return base(bold).deriveFont((float) size);
	}

	private static int style(boolean bold)
	{
		return bold ? Font.BOLD : Font.PLAIN;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.bacursortimer;

/**
 * Wave duration measured in game ticks, so the displayed time moves in exact
 * 0.6 second steps in lockstep with the server rather than drifting with wall-clock time.
 */
class WaveClock
{
	private static final int NOT_RUNNING = -1;

	private int startTick = NOT_RUNNING;

	void start(int tick)
	{
		startTick = tick;
	}

	void stop()
	{
		startTick = NOT_RUNNING;
	}

	boolean isRunning()
	{
		return startTick != NOT_RUNNING;
	}

	int elapsedTicks(int currentTick)
	{
		return Math.max(0, currentTick - startTick);
	}

	/**
	 * Formats a tick count as whole seconds and tenths ({@code 4.2}, {@code 123.6}),
	 * never rolling over into minutes. A tick is exactly six tenths of a second, so
	 * integer arithmetic gives the exact value with no rounding.
	 */
	static String format(int ticks)
	{
		int tenths = ticks * 6;
		return (tenths / 10) + "." + (tenths % 10);
	}
}

package com.bacursortimer;

import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

class BACursorTimerOverlayTest
{
	private static FontMetrics metrics()
	{
		Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		return graphics.getFontMetrics(TimerFont.RUNESCAPE.font(true, 16));
	}

	@Nested
	class TestBackgroundBounds
	{
		@Test
		void coversTheTextAndItsShadowWithPadding()
		{
			FontMetrics metrics = metrics();
			Rectangle bounds = BACursorTimerOverlay.backgroundBounds(100, 50, metrics, "12.6");

			assertEquals(98, bounds.x);
			assertEquals(50 - metrics.getAscent() - 2, bounds.y);
			assertEquals(metrics.stringWidth("12.6") + 5, bounds.width);
			assertEquals(metrics.getAscent() + metrics.getDescent() + 5, bounds.height);
		}

		@Test
		void growsWithTheText()
		{
			FontMetrics metrics = metrics();

			assertTrue(BACursorTimerOverlay.backgroundBounds(0, 0, metrics, "100.2").width
				> BACursorTimerOverlay.backgroundBounds(0, 0, metrics, "9.6").width);
		}
	}
}

